    h,w=len(grid),len(grid[0])
    # Connected same-color objects slide toward the uniform wall until blocked.
    if len(set(grid[0]))==1:
        dr,dc=-1,0; wallrow=0; wallcol=None
    elif all(grid[r][0]==grid[0][0] and grid[r][0]!=0 for r in range(h)):
        dr,dc=0,-1; wallrow=None; wallcol=0
    else:
        return [row[:] for row in grid]
    seen=set(); objs=[]
    for r in range(h):
      for c in range(w):
       color=grid[r][c]
       if color and (r,c) not in seen and not (r==wallrow if wallrow is not None else c==wallcol):
        st=[(r,c)];seen.add((r,c));cells=[]
        while st:
         a,b=st.pop();cells.append((a,b))
         for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
          p,q=a+da,b+db
          if 0<=p<h and 0<=q<w and grid[p][q]==color and (p,q) not in seen and not (p==wallrow if wallrow is not None else q==wallcol):
           seen.add((p,q));st.append((p,q))
        objs.append((color,cells))
    # One-cell gravity steps; nearest objects move first each round.
    objs.sort(key=lambda ob:min(r for r,c in ob[1]) if dr<0 else min(c for r,c in ob[1]))
    positions=[cells[:] for _,cells in objs]
    moved=True
    while moved:
      moved=False
      for i,cells in enumerate(positions):
       others={(r,c) for j,cs in enumerate(positions) if j!=i for r,c in cs}
       nxt=[(r+dr,c+dc) for r,c in cells]
       if all(0<=r<h and 0<=c<w and (wallrow is None or r>wallrow) and (wallcol is None or c>wallcol) and (r,c) not in others for r,c in nxt):
        positions[i]=nxt;moved=True
    out=[[0]*w for _ in range(h)]
    if wallrow is not None: out[wallrow]=grid[wallrow][:]
    else:
      for r in range(h):out[r][wallcol]=grid[r][wallcol]
    for (color,_),cells in zip(objs,positions):
      for r,c in cells:out[r][c]=color
    return out
