    # A full monochrome edge is the wall attracting all rigid colored components.
    if len(set(grid[0]))==1:
        axis,wall,dr,dc=0,0,-1,0
        inside=lambda r,c:r>0
    elif len(set(grid[-1]))==1:
        axis,wall,dr,dc=0,h-1,1,0
        inside=lambda r,c:r<h-1
    elif all(grid[r][0]==grid[0][0] and grid[r][0]!=0 for r in range(h)):
        axis,wall,dr,dc=1,0,0,-1
        inside=lambda r,c:c>0
    elif all(grid[r][-1]==grid[0][-1] and grid[r][-1]!=0 for r in range(h)):
        axis,wall,dr,dc=1,w-1,0,1
        inside=lambda r,c:c<w-1
    else:
        return [row[:] for row in grid]
    seen=set(); objs=[]
    for r in range(h):
      for c in range(w):
       col=grid[r][c]
       if col and inside(r,c) and (r,c) not in seen:
        st=[(r,c)];seen.add((r,c));cells=[]
        while st:
         a,b=st.pop();cells.append((a,b))
         for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
          p,q=a+da,b+db
          if 0<=p<h and 0<=q<w and inside(p,q) and grid[p][q]==col and (p,q) not in seen:
           seen.add((p,q));st.append((p,q))
        objs.append((col,cells))
    # Settle components nearest the wall first, maintaining each component's shape.
    if dr<0: objs.sort(key=lambda o:min(r for r,c in o[1]))
    elif dr>0: objs.sort(key=lambda o:-max(r for r,c in o[1]))
    elif dc<0: objs.sort(key=lambda o:min(c for r,c in o[1]))
    else: objs.sort(key=lambda o:-max(c for r,c in o[1]))
    placed=[]
    for col,cells in objs:
      occupied={(r,c) for _,cs in placed for r,c in cs}
      shift=0
      while True:
