def transform(grid):
    h, w = len(grid), len(grid[0])
    if len(set(grid[0])) == 1:
        wall_row, wall_col, dr, dc = 0, None, 1, 0
        inside = lambda r, c: r > 0
    elif len(set(grid[-1])) == 1:
        wall_row, wall_col, dr, dc = h - 1, None, -1, 0
        inside = lambda r, c: r < h - 1
    elif all(grid[r][0] == grid[0][0] and grid[r][0] != 0 for r in range(h)):
        wall_row, wall_col, dr, dc = None, 0, 0, -1
        inside = lambda r, c: c > 0
    elif all(grid[r][-1] == grid[0][-1] and grid[r][-1] != 0 for r in range(h)):
        wall_row, wall_col, dr, dc = None, w - 1, 0, 1
        inside = lambda r, c: c < w - 1
    else:
        return [row[:] for row in grid]

    seen, objects = set(), []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color and inside(r, c) and (r, c) not in seen:
                stack, cells = [(r, c)], []
                seen.add((r, c))
                while stack:
                    a, b = stack.pop()
                    cells.append((a, b))
                    for da, db in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        p, q = a + da, b + db
                        if (0 <= p < h and 0 <= q < w and inside(p, q)
                                and grid[p][q] == color and (p, q) not in seen):
                            seen.add((p, q))
                            stack.append((p, q))
                objects.append((color, cells))

    # Simulate rigid pieces sliding one cell per step toward the colored wall.
    positions = [cells[:] for _, cells in objects]
    while True:
        moves = []
        for i, cells in enumerate(positions):
            occupied = {cell for j, other in enumerate(positions) if j != i for cell in other}
            nxt = [(r + dr, c + dc) for r, c in cells]
            moves.append(all(0 <= r < h and 0 <= c < w and inside(r, c)
                             and (r, c) not in occupied for r, c in nxt))
        if not any(moves):
            break
        positions = [[(r + dr, c + dc) for r, c in cells] if moves[i] else cells
                     for i, cells in enumerate(positions)]

    out = [[0] * w for _ in range(h)]
    if wall_row is not None:
        out[wall_row] = grid[wall_row][:]
    else:
        for r in range(h):
            out[r][wall_col] = grid[r][wall_col]
    for (color, _), cells in zip(objects, positions):
        for r, c in cells:
            out[r][c] = color
    return out
